process.env.NODE_ENV = 'test';

import request from 'supertest';
import app from '../app';
import db from '../config/db';

async function runTests() {
  console.log('🧪 Starting Vehicle Rental Management Integration Tests...\n');

  let token = '';
  let createdVehicleId = 0;
  let createdRentalId = 0;

  try {
    // 1. Healthcheck
    console.log('1. Testing GET /health ...');
    const healthRes = await request(app).get('/health');
    console.assert(healthRes.status === 200, `Expected status 200, got ${healthRes.status}`);
    console.assert(healthRes.body.success === true, 'Expected success === true');
    console.log('✅ Healthcheck passed.\n');

    // 2. Auth Login Failure
    console.log('2. Testing POST /auth/login (Invalid Credentials) ...');
    const failLoginRes = await request(app)
      .post('/auth/login')
      .send({ email: 'admin@vrm.com', password: 'WrongPassword' });
    console.assert(failLoginRes.status === 401, `Expected 401, got ${failLoginRes.status}`);
    console.log('✅ Invalid login rejected.\n');

    // 3. Auth Login Success
    console.log('3. Testing POST /auth/login (Valid Credentials) ...');
    const loginRes = await request(app)
      .post('/auth/login')
      .send({ email: 'admin@vrm.com', password: 'Password123!' });
    console.assert(loginRes.status === 200, `Expected 200, got ${loginRes.status}`);
    console.assert(!!loginRes.body.data.token, 'Expected JWT token');
    token = loginRes.body.data.token;
    console.log(`✅ Login successful. Received JWT token.\n`);

    // 4. Protected Route Rejection without Auth Header
    console.log('4. Testing Protected Route GET /vehicles (No Auth Header) ...');
    const noAuthRes = await request(app).get('/vehicles');
    console.assert(noAuthRes.status === 401, `Expected 401, got ${noAuthRes.status}`);
    console.log('✅ Unauthenticated request blocked.\n');

    // 5. GET /vehicles (With Auth Header)
    console.log('5. Testing GET /vehicles ...');
    const vehiclesRes = await request(app).get('/vehicles').set('Authorization', `Bearer ${token}`);
    console.assert(vehiclesRes.status === 200, `Expected 200, got ${vehiclesRes.status}`);
    console.assert(vehiclesRes.body.data.length >= 3, 'Expected at least 3 seeded vehicles');
    console.log(`✅ Retrieved ${vehiclesRes.body.data.length} vehicles.\n`);

    // 6. POST /vehicles (Create New Vehicle)
    console.log('6. Testing POST /vehicles ...');
    const uniquePlate = `POR-${Date.now().toString().slice(-4)}`;
    const createVehicleRes = await request(app)
      .post('/vehicles')
      .set('Authorization', `Bearer ${token}`)
      .field('name', 'Porsche 911 GT3')
      .field('plate_number', uniquePlate)
      .field('category', 'Sports')
      .field('daily_rate', '250.00');
    console.assert(createVehicleRes.status === 201, `Expected 201, got ${createVehicleRes.status}`);
    createdVehicleId = createVehicleRes.body.data.id;
    console.log(
      `✅ Created vehicle ID: ${createdVehicleId} (${createVehicleRes.body.data.name})\n`
    );

    // 7. GET /vehicles/:id
    console.log(`7. Testing GET /vehicles/${createdVehicleId} ...`);
    const getVehicleRes = await request(app)
      .get(`/vehicles/${createdVehicleId}`)
      .set('Authorization', `Bearer ${token}`);
    console.assert(getVehicleRes.status === 200, `Expected 200, got ${getVehicleRes.status}`);
    console.assert(
      getVehicleRes.body.data.plate_number === uniquePlate,
      `Expected plate ${uniquePlate}`
    );
    console.log('✅ Vehicle details retrieved successfully.\n');

    // 8. PUT /vehicles/:id (Update Daily Rate)
    console.log(`8. Testing PUT /vehicles/${createdVehicleId} ...`);
    const updateVehicleRes = await request(app)
      .put(`/vehicles/${createdVehicleId}`)
      .set('Authorization', `Bearer ${token}`)
      .field('daily_rate', '280.00');
    console.assert(updateVehicleRes.status === 200, `Expected 200, got ${updateVehicleRes.status}`);
    console.assert(Number(updateVehicleRes.body.data.daily_rate) === 280.0, 'Expected rate 280.00');
    console.log('✅ Vehicle updated successfully.\n');

    // 9. POST /rentals (Create Valid Rental for Porsche)
    console.log(
      '9. Testing POST /rentals (Valid Booking: 2026-08-15 to 2026-08-17 - 3 Days @ 280.00 = 840.00) ...'
    );
    const createRentalRes = await request(app)
      .post('/rentals')
      .set('Authorization', `Bearer ${token}`)
      .send({
        vehicle_id: createdVehicleId,
        customer_name: 'Robert Miller',
        customer_phone: '+1-555-9988',
        start_date: '2026-08-15',
        end_date: '2026-08-17'
      });
    console.assert(createRentalRes.status === 201, `Expected 201, got ${createRentalRes.status}`);
    console.assert(
      Number(createRentalRes.body.data.total_amount) === 840.0,
      `Expected $840.00, got ${createRentalRes.body.data.total_amount}`
    );
    createdRentalId = createRentalRes.body.data.id;
    console.log(
      `✅ Rental created ID: ${createdRentalId}, Total Amount: $${createRentalRes.body.data.total_amount}\n`
    );

    // 10. POST /rentals (Double Booking Conflict Test -> Expect 409)
    console.log('10. Testing POST /rentals (Overlapping Booking -> Expect 409 Conflict) ...');
    const overlapRes = await request(app)
      .post('/rentals')
      .set('Authorization', `Bearer ${token}`)
      .send({
        vehicle_id: createdVehicleId,
        customer_name: 'Jane Doe',
        customer_phone: '+1-555-7766',
        start_date: '2026-08-16', // Overlaps with 2026-08-15 to 2026-08-17
        end_date: '2026-08-20'
      });
    console.assert(overlapRes.status === 409, `Expected 409 Conflict, got ${overlapRes.status}`);
    console.assert(overlapRes.body.message.includes('already booked'), 'Expected conflict message');
    console.log(`✅ Double booking correctly rejected with HTTP 409 Conflict.\n`);

    // 11. POST /rentals (Single Day Booking Test -> Same Start & End Date = 1 Day)
    console.log('11. Testing POST /rentals (Same Start/End Date -> 1 Day Calculation) ...');
    const singleDayRes = await request(app)
      .post('/rentals')
      .set('Authorization', `Bearer ${token}`)
      .send({
        vehicle_id: createdVehicleId,
        customer_name: 'Same Day User',
        customer_phone: '+1-555-1111',
        start_date: '2026-08-01',
        end_date: '2026-08-01'
      });
    console.assert(singleDayRes.status === 201, `Expected 201, got ${singleDayRes.status}`);
    console.assert(
      Number(singleDayRes.body.data.total_amount) === 280.0,
      `Expected 1 day amount $280.00, got ${singleDayRes.body.data.total_amount}`
    );
    console.log('✅ Single-day booking calculated correctly as 1 day.\n');

    // 12. GET /reports/rentals?month=2026-08 (Monthly Report Proration Verification)
    console.log(
      '12. Testing GET /reports/rentals?month=2026-08 (Verifying Cross-Month Proration) ...'
    );
    const reportRes = await request(app)
      .get('/reports/rentals?month=2026-08')
      .set('Authorization', `Bearer ${token}`);
    console.assert(reportRes.status === 200, `Expected 200, got ${reportRes.status}`);

    const reportData = reportRes.body.data;
    console.log(`Report Month: ${reportData.month}`);

    // Find Toyota Camry in report (which had rental July 29 - Aug 3)
    const camryReport = reportData.vehicles.find(
      (v: { plate_number: string }) => v.plate_number === 'ABC-1234'
    );
    console.assert(camryReport !== undefined, 'Expected Toyota Camry in report');
    console.assert(
      camryReport.days_rented === 3,
      `Expected 3 prorated days in Aug for July 29-Aug 3 rental, got ${camryReport.days_rented}`
    );
    console.assert(
      camryReport.revenue === 150,
      `Expected $150 revenue for 3 days @ $50/day, got ${camryReport.revenue}`
    );

    console.log(
      `✅ Cross-month rental proration verified: July 29 - Aug 3 rental contributed exactly 3 days ($150.00) to August report!`
    );
    console.log(
      `🏆 Highest Revenue Vehicle for Aug 2026: ${reportData.highest_revenue_vehicle?.name} ($${reportData.highest_revenue_vehicle?.revenue})\n`
    );

    // 13. DELETE /vehicles/:id (Soft Delete)
    console.log(`13. Testing DELETE /vehicles/${createdVehicleId} (Soft Delete) ...`);
    const deleteVehicleRes = await request(app)
      .delete(`/vehicles/${createdVehicleId}`)
      .set('Authorization', `Bearer ${token}`);
    console.assert(deleteVehicleRes.status === 200, `Expected 200, got ${deleteVehicleRes.status}`);

    const verifyDeletedRes = await request(app)
      .get(`/vehicles/${createdVehicleId}`)
      .set('Authorization', `Bearer ${token}`);
    console.assert(
      verifyDeletedRes.status === 404,
      `Expected 404 for soft deleted vehicle, got ${verifyDeletedRes.status}`
    );
    console.log('✅ Soft delete verified.\n');

    console.log('🎉 ALL INTEGRATION TESTS PASSED SUCCESSFULLY!');
    process.exit(0);
  } catch (err) {
    console.error('❌ Test suite failed:', err);
    process.exit(1);
  } finally {
    await db.destroy();
  }
}

runTests();

import { Application } from 'express';
import swaggerUi from 'swagger-ui-express';

const swaggerDocument = {
  openapi: '3.0.0',
  info: {
    title: 'Vehicle Rental Management API',
    version: '1.0.0',
    description:
      'REST API for staff login, vehicle fleet management, rental booking overlap checks, and monthly activity reports.'
  },
  servers: [
    {
      url: 'http://localhost:3000',
      description: 'Local Development Server'
    }
  ],
  components: {
    securitySchemes: {
      bearerAuth: {
        type: 'http',
        scheme: 'bearer',
        bearerFormat: 'JWT',
        description: 'Enter your JWT Bearer token'
      }
    },
    schemas: {
      ApiResponse: {
        type: 'object',
        properties: {
          success: { type: 'boolean', example: true },
          message: { type: 'string', example: 'Operation completed successfully' },
          data: { type: 'object' }
        }
      },
      ErrorResponse: {
        type: 'object',
        properties: {
          success: { type: 'boolean', example: false },
          message: { type: 'string', example: 'Error description' }
        }
      },
      LoginRequest: {
        type: 'object',
        required: ['email', 'password'],
        properties: {
          email: { type: 'string', example: 'admin@vrm.com' },
          password: { type: 'string', example: 'Password123!' }
        }
      },
      VehicleInput: {
        type: 'object',
        required: ['name', 'plate_number', 'category', 'daily_rate'],
        properties: {
          name: { type: 'string', example: 'Tesla Model 3' },
          plate_number: { type: 'string', example: 'EV-9999' },
          category: { type: 'string', example: 'Electric' },
          daily_rate: { type: 'number', example: 100.0 },
          photo: { type: 'string', format: 'binary', description: 'Vehicle image file' }
        }
      },
      RentalInput: {
        type: 'object',
        required: ['vehicle_id', 'customer_name', 'customer_phone', 'start_date', 'end_date'],
        properties: {
          vehicle_id: { type: 'integer', example: 1 },
          customer_name: { type: 'string', example: 'John Doe' },
          customer_phone: { type: 'string', example: '+1-555-0199' },
          start_date: { type: 'string', format: 'date', example: '2026-08-15' },
          end_date: { type: 'string', format: 'date', example: '2026-08-20' },
          status: {
            type: 'string',
            enum: ['booked', 'ongoing', 'completed', 'cancelled'],
            example: 'booked'
          }
        }
      }
    }
  },
  paths: {
    '/auth/login': {
      post: {
        tags: ['Auth'],
        summary: 'Staff Login',
        description: 'Authenticate staff user and return JWT bearer token',
        requestBody: {
          required: true,
          content: {
            'application/json': {
              schema: { $ref: '#/components/schemas/LoginRequest' }
            }
          }
        },
        responses: {
          '200': {
            description: 'Login successful',
            content: {
              'application/json': {
                schema: {
                  type: 'object',
                  properties: {
                    success: { type: 'boolean', example: true },
                    message: { type: 'string', example: 'Login successful' },
                    data: {
                      type: 'object',
                      properties: {
                        token: { type: 'string', example: 'eyJhbGciOiJIUzI1NiIsIn...' },
                        staff: {
                          type: 'object',
                          properties: {
                            id: { type: 'integer', example: 1 },
                            email: { type: 'string', example: 'admin@vrm.com' },
                            name: { type: 'string', example: 'System Administrator' }
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
          },
          '401': {
            description: 'Invalid email or password',
            content: {
              'application/json': { schema: { $ref: '#/components/schemas/ErrorResponse' } }
            }
          }
        }
      }
    },
    '/vehicles': {
      get: {
        tags: ['Vehicles'],
        summary: 'Get all vehicles',
        security: [{ bearerAuth: [] }],
        parameters: [
          { name: 'page', in: 'query', schema: { type: 'integer', default: 1 } },
          { name: 'limit', in: 'query', schema: { type: 'integer', default: 10 } },
          { name: 'category', in: 'query', schema: { type: 'string' } },
          { name: 'name', in: 'query', schema: { type: 'string' } }
        ],
        responses: {
          '200': {
            description: 'Vehicles retrieved successfully',
            content: {
              'application/json': {
                schema: {
                  type: 'object',
                  properties: {
                    success: { type: 'boolean', example: true },
                    message: { type: 'string', example: 'Vehicles retrieved successfully' },
                    data: {
                      type: 'array',
                      items: {
                        type: 'object',
                        properties: {
                          id: { type: 'integer', example: 1 },
                          name: { type: 'string', example: 'Toyota Camry' },
                          plate_number: { type: 'string', example: 'ABC-1234' },
                          category: { type: 'string', example: 'Sedan' },
                          daily_rate: { type: 'number', example: 50.0 },
                          photo_path: { type: 'string', example: 'uploads/vehicles/vehicle-1.jpg' }
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      },
      post: {
        tags: ['Vehicles'],
        summary: 'Create a new vehicle',
        security: [{ bearerAuth: [] }],
        requestBody: {
          required: true,
          content: {
            'multipart/form-data': {
              schema: { $ref: '#/components/schemas/VehicleInput' }
            }
          }
        },
        responses: {
          '201': {
            description: 'Vehicle created successfully',
            content: {
              'application/json': { schema: { $ref: '#/components/schemas/ApiResponse' } }
            }
          }
        }
      }
    },
    '/vehicles/{id}': {
      get: {
        tags: ['Vehicles'],
        summary: 'Get vehicle by ID',
        security: [{ bearerAuth: [] }],
        parameters: [{ name: 'id', in: 'path', required: true, schema: { type: 'integer' } }],
        responses: {
          '200': {
            description: 'Vehicle details',
            content: {
              'application/json': { schema: { $ref: '#/components/schemas/ApiResponse' } }
            }
          },
          '404': { description: 'Vehicle not found' }
        }
      },
      put: {
        tags: ['Vehicles'],
        summary: 'Update vehicle',
        security: [{ bearerAuth: [] }],
        parameters: [{ name: 'id', in: 'path', required: true, schema: { type: 'integer' } }],
        requestBody: {
          content: {
            'multipart/form-data': {
              schema: { $ref: '#/components/schemas/VehicleInput' }
            }
          }
        },
        responses: {
          '200': {
            description: 'Vehicle updated',
            content: {
              'application/json': { schema: { $ref: '#/components/schemas/ApiResponse' } }
            }
          }
        }
      },
      delete: {
        tags: ['Vehicles'],
        summary: 'Soft delete vehicle',
        security: [{ bearerAuth: [] }],
        parameters: [{ name: 'id', in: 'path', required: true, schema: { type: 'integer' } }],
        responses: {
          '200': {
            description: 'Vehicle soft deleted',
            content: {
              'application/json': { schema: { $ref: '#/components/schemas/ApiResponse' } }
            }
          }
        }
      }
    },
    '/rentals': {
      get: {
        tags: ['Rentals'],
        summary: 'Get all rentals',
        security: [{ bearerAuth: [] }],
        parameters: [
          { name: 'vehicle_id', in: 'query', schema: { type: 'integer' } },
          {
            name: 'status',
            in: 'query',
            schema: { type: 'string', enum: ['booked', 'ongoing', 'completed', 'cancelled'] }
          },
          { name: 'start_date', in: 'query', schema: { type: 'string', format: 'date' } },
          { name: 'end_date', in: 'query', schema: { type: 'string', format: 'date' } }
        ],
        responses: {
          '200': {
            description: 'Rentals list',
            content: {
              'application/json': { schema: { $ref: '#/components/schemas/ApiResponse' } }
            }
          }
        }
      },
      post: {
        tags: ['Rentals'],
        summary: 'Create rental booking',
        security: [{ bearerAuth: [] }],
        requestBody: {
          required: true,
          content: {
            'application/json': { schema: { $ref: '#/components/schemas/RentalInput' } }
          }
        },
        responses: {
          '201': {
            description: 'Rental created successfully',
            content: {
              'application/json': { schema: { $ref: '#/components/schemas/ApiResponse' } }
            }
          },
          '409': {
            description: 'Vehicle already booked for overlapping dates',
            content: {
              'application/json': { schema: { $ref: '#/components/schemas/ErrorResponse' } }
            }
          }
        }
      }
    },
    '/rentals/{id}': {
      get: {
        tags: ['Rentals'],
        summary: 'Get rental by ID',
        security: [{ bearerAuth: [] }],
        parameters: [{ name: 'id', in: 'path', required: true, schema: { type: 'integer' } }],
        responses: {
          '200': {
            description: 'Rental details',
            content: {
              'application/json': { schema: { $ref: '#/components/schemas/ApiResponse' } }
            }
          }
        }
      },
      put: {
        tags: ['Rentals'],
        summary: 'Update rental',
        security: [{ bearerAuth: [] }],
        parameters: [{ name: 'id', in: 'path', required: true, schema: { type: 'integer' } }],
        requestBody: {
          content: {
            'application/json': { schema: { $ref: '#/components/schemas/RentalInput' } }
          }
        },
        responses: {
          '200': {
            description: 'Rental updated',
            content: {
              'application/json': { schema: { $ref: '#/components/schemas/ApiResponse' } }
            }
          },
          '409': { description: 'Date conflict on update' }
