      },
      delete: {
        tags: ['Rentals'],
        summary: 'Delete rental',
        security: [{ bearerAuth: [] }],
        parameters: [{ name: 'id', in: 'path', required: true, schema: { type: 'integer' } }],
        responses: {
          '200': {
            description: 'Rental deleted',
            content: {
              'application/json': { schema: { $ref: '#/components/schemas/ApiResponse' } }
            }
          }
        }
      }
    },
    '/reports/rentals': {
      get: {
        tags: ['Reports'],
        summary: 'Get monthly rental activity report',
        security: [{ bearerAuth: [] }],
        parameters: [
          {
            name: 'month',
            in: 'query',
            required: true,
            schema: { type: 'string', example: '2026-08' },
            description: 'YYYY-MM format'
          },
          { name: 'vehicle_id', in: 'query', schema: { type: 'integer' } }
        ],
        responses: {
          '200': {
            description: 'Monthly report generated with prorated rental days and revenue',
            content: {
              'application/json': {
                schema: {
                  type: 'object',
                  properties: {
                    success: { type: 'boolean', example: true },
                    message: {
                      type: 'string',
                      example: 'Monthly rental report generated successfully'
